{"explanation":"Inverse functions swap inputs and outputs: if e^t = u, then ln(u) = t. So the point (t, u) on y = e^x corresponds to (u, t) on y = ln(x). Swapping coordinates reflects a point across y = x; move the slider to see this for different points.","manimCode":"const ax = new Axes({
  xRange: [-3, 7, 1],
  yRange: [-3, 7, 1],
  xLength: 6.2,
  yLength: 6.2,
  tips: false
});
ax.moveTo([-1.5, -0.15, 0]);

const expCurve = ax.plot(x => Math.exp(x), {
  color: BLUE,
  xRange: [-2.5, Math.log(6.5)],
  numSamples: 300
});
const logCurve = ax.plot(x => Math.log(x), {
  color: ORANGE,
  xRange: [Math.exp(-2.5), 6.5],
  numSamples: 300
});
const mirror = new Line({
  start: ax.c2p(-2.7, -2.7),
  end: ax.c2p(6.7, 6.7),
  color: GRAY
});
mirror.setStrokeWidth(2);
mirror.setOpacity(0.75);

const title = new Text({ text: 'Inverse functions are reflections', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.45, 0]);
const expLabel = new MathTex({ latex: 'y=e^x', color: BLUE });
const logLabel = new MathTex({ latex: 'y=\\ln(x)', color: ORANGE });
const mirrorLabel = new MathTex({ latex: 'y=x', color: GRAY });
await Promise.all([expLabel.waitForRender(), logLabel.waitForRender(), mirrorLabel.waitForRender()]);
expLabel.moveTo([4.2, 1.55, 0]);
logLabel.moveTo([4.2, 0.8, 0]);
mirrorLabel.moveTo([4.2, 0.05, 0]);

await scene.play(new Write(title));
await scene.play(new Create(ax));
await scene.play(new Create(mirror));
await scene.play(new AnimationGroup([new Create(expCurve), new Create(logCurve)]));
scene.add(expLabel, logLabel, mirrorLabel);

let t = 0.6;
const a = new Dot({ point: ax.c2p(t, Math.exp(t)), color: BLUE });
const b = new Dot({ point: ax.c2p(Math.exp(t), t), color: ORANGE });
const midpoint = new Dot({ point: ax.c2p((t + Math.exp(t)) / 2, (t + Math.exp(t)) / 2), color: YELLOW });
const pairSegment = new Polygon({ vertices: [a.getCenter(), b.getCenter()], color: YELLOW });
pairSegment.setStrokeWidth(2);
pairSegment.setFillOpacity(0);

function updatePair() {
  const u = Math.exp(t);
  a.moveTo(ax.c2p(t, u));
  b.moveTo(ax.c2p(u, t));
  midpoint.moveTo(ax.c2p((t + u) / 2, (t + u) / 2));
  pairSegment.setVertices([a.getCenter(), b.getCenter()]);
}
scene.add(pairSegment, a, b, midpoint);

const controls = new Controls(scene, { position: 'bottom-right', width: 250 });
controls.addSlider({
  label: 'Choose t', min: -1.5, max: 1.5, value: t, step: 0.05,
  onChange: v => { t = v; updatePair(); }
});

await scene.wait(999999);"}

